export const canonical50CollisionDatabaseBytes = (): Buffer => {
  const recipe = readFileSync(new URL("./canonical50-collision-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== canonical50CollisionFixture.generatorSha256) {
    throw new Error("Canonical50 collision generator integrity mismatch.");
  }
  const bytes = gunzipSync(Buffer.from(image, "base64"), { maxOutputLength: canonical50CollisionFixture.databaseBytes });
  if (bytes.length !== canonical50CollisionFixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== canonical50CollisionFixture.databaseSha256) {
    throw new Error("Canonical50 collision database integrity mismatch.");
  }
  return bytes;
};
